using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

[ApiController]
[Route("api/envios")]
public class EnviosController(DespachoDb db) : ControllerBase
{
    [HttpGet("{id:int}")]
    public async Task<ActionResult<Envio>> Uno(int id)
    {
        var e = await db.Envios.AsNoTracking().FirstOrDefaultAsync(x => x.Id == id);
        return e is null ? NotFound() : e;
    }
}

